import base64
def b64(f): return 'data:image/png;base64,'+base64.b64encode(open(f,'rb').read()).decode()
CSS='''*{box-sizing:border-box;margin:0}body{width:390px;height:760px;overflow:hidden;font:13px/1.3 system-ui,Arial,sans-serif;color:#fff;background:#0b1014;position:relative}
.bg{position:absolute;inset:0;background-size:cover;background-position:center}.g{color:#ffd76a}.dim{color:#9aa6b0}.b{font-weight:800}
.tag{position:absolute;top:10px;left:10px;background:#000a;border:1px solid #ffd76a;color:#ffd76a;font-weight:800;font-size:11px;letter-spacing:.08em;border-radius:6px;padding:4px 8px;z-index:9}
.btn{background:#2f8cff;border-radius:10px;padding:12px;text-align:center;font-weight:800;letter-spacing:.04em}.btn.go{background:#2faa4f}.btn.gr{background:#39424b}
.card{background:#0e151bf2;border-radius:14px;padding:12px}'''
def page(name,body,extra=''):
    open(name,'w').write(f'<meta charset=utf8><style>{CSS}{extra}</style>{body}')
bg1,bg2,bg3=b64('bg1.png'),b64('bg2.png'),b64('bg3.png')
# A: one man at a time, swipe cards, a medal you pin yourself
page('A1.html',f'''<div class=bg style="background-image:url({bg1});filter:brightness(.85)"></div><div class=tag>A · SWIPE THE SQUAD</div>
<div style="position:absolute;top:44px;left:0;right:0;text-align:center"><div class="g b" style="font-size:30px;letter-spacing:.14em;text-shadow:0 2px 12px #000">VICTORY</div><div class=b style="letter-spacing:.2em;font-size:11px">CHAPTER 1 · D-DAY</div></div>
<div style="position:absolute;left:0;right:0;top:330px;display:flex;gap:10px;padding:0 34px;transform:translateX(-0px)">
 <div class=card style="min-width:322px;border-top:4px solid #58c4f6;box-shadow:0 10px 30px #000a">
  <div style="display:flex;justify-content:space-between;align-items:center"><div><div class=b style="font-size:24px">Reed</div><div class=b style="color:#58c4f6;font-size:10px;letter-spacing:.12em">ALPHA · MEDIC</div></div>
   <div style="width:58px;height:58px;border-radius:50%;border:4px solid #ffd76a;display:flex;flex-direction:column;align-items:center;justify-content:center"><span style="font-size:8px" class="dim b">LEVEL</span><span class="b g" style="font-size:22px;line-height:1">2</span></div></div>
  <div style="margin:10px 0;padding:9px 10px;border-radius:10px;background:linear-gradient(90deg,#ffd76a33,#ffd76a08);border-left:3px solid #ffd76a"><div class="g b" style="letter-spacing:.1em;font-size:15px">★ MOST VALUABLE</div><div>7 kills: the company's best today</div></div>
  <div style="display:flex;gap:6px;text-align:center">''' + ''.join(f'<div style="flex:1;background:#18222b;border-radius:9px;padding:6px"><div class="b" style="font-size:19px">{v}</div><div class="dim b" style="font-size:8.5px;letter-spacing:.08em">{k}</div></div>' for k,v in [('KILLS',7),('REVIVES',0),('TIMES DOWN',0),('GRENADES',2)]) + '''</div>
  <div style="margin-top:10px;display:flex;align-items:center;gap:8px"><div style="flex:1;height:12px;background:#222b33;border-radius:6px;overflow:hidden"><div style="width:62%;height:100%;background:linear-gradient(90deg,#e0a92e,#ffe08a)"></div></div><span class="g b">+440 XP</span></div>
  <div style="margin-top:8px;background:#ffd76a2e;color:#ffe08a;border-radius:8px;padding:7px;text-align:center;font-weight:800;font-size:12px">▲ LEVEL UP · choose one</div>
  <div style="display:flex;gap:6px;margin-top:6px"><div class=btn style="flex:1;background:#1d3a2a;border:1.5px solid #2faa4f;font-size:11px">STEADY HANDS<br><span class=dim style="font-weight:400">revives 2 s faster</span></div><div class=btn style="flex:1;background:#18222b;border:1.5px solid #39424b;font-size:11px">TOUGH<br><span class=dim style="font-weight:400">+10 health</span></div></div>
 </div>
 <div class=card style="min-width:322px;border-top:4px solid #58c4f6;opacity:.75"><div class=b style="font-size:24px">Carter</div></div></div>
<div style="position:absolute;bottom:64px;left:0;right:0;text-align:center"><span style="letter-spacing:6px;color:#ffd76a">●</span><span style="letter-spacing:6px;color:#44525e">●●●●●●●</span><div class="dim b" style="font-size:10px;letter-spacing:.1em;margin-top:4px">‹ SWIPE › · 1 OF 8</div></div>
<div style="position:absolute;bottom:12px;left:12px;right:12px;display:flex;gap:8px"><div class="btn gr" style="flex:1">SEE ALL</div><div class=btn style="flex:2">NEXT MAN ▸</div></div>''')
# B: the awards table: you hand out the medals
page('B1.html',f'''<div class=bg style="background-image:url({bg3});filter:brightness(.45) blur(2px)"></div><div class=tag>B · YOU GIVE THE MEDALS</div>
<div style="position:absolute;top:46px;left:14px;right:14px"><div class="g b" style="font-size:22px;letter-spacing:.12em">AWARDS</div><div class=dim>Chapter 1 · D-Day · 23:41 · 52 enemy down · 3 of ours lost</div>
<div class=card style="margin-top:10px"><div class="b g" style="font-size:11px;letter-spacing:.1em">★ COMPANY MEDAL · PICK ONE MAN</div><div class=dim style="font-size:11px;margin:2px 0 8px">The man you pick gets a star, +100 XP and a permanent +2 to every stat.</div>
'''+''.join(f'''<div style="display:flex;align-items:center;gap:10px;background:{'#2a2410' if s else '#18222b'};border:1.5px solid {'#ffd76a' if s else '#2c3a46'};border-radius:10px;padding:8px 10px;margin-bottom:6px"><div style="width:38px;height:38px;border-radius:50%;background:{c};display:flex;align-items:center;justify-content:center;font-weight:800">{n[0]}</div><div style="flex:1"><div class=b style="font-size:15px">{n} <span class=dim style="font-size:10px;font-weight:400">{r}</span></div><div style="font-size:11px" class={'g' if s else 'dim'}>{w}</div></div><div style="font-size:22px">{'★' if s else '☆'}</div></div>''' for n,r,w,c,s in [('Reed','Alpha · Medic','7 kills, never went down','#2a6f95',1),('Carter','Alpha · Gunner','Brought 2 men back under fire','#2a6f95',0),('Walsh','Bravo · Gunner','6 kills, 3 in a row','#8a6a1e',0)])+'''</div>
<div class=card style="margin-top:10px"><div class="b" style="font-size:11px;letter-spacing:.1em;color:#7ed29a">PROMOTIONS · 5 MEN LEVELLED UP</div>
<div style="display:flex;gap:6px;margin-top:8px;overflow:hidden">'''+''.join(f'<div style="min-width:76px;background:#18222b;border-radius:9px;padding:7px;text-align:center"><div class=b>{n}</div><div class="g b" style="font-size:16px">Lv {l}</div><div style="font-size:9px;color:#7ed29a" class=b>TAP: PERK</div></div>' for n,l in [('Reed',2),('Carter',2),('Zielinski',2),('Irwin',2),('Walsh',2)])+'''</div></div>
<div class=card style="margin-top:10px;border-left:3px solid #ff6a5e"><div class=b style="color:#ff9d93;font-size:11px;letter-spacing:.1em">✚ WOUNDED · ROSSI</div><div style="display:flex;gap:8px;align-items:center;margin-top:6px"><div class=dim style="flex:1;font-size:11px">Sits out the next mission unless treated.</div><div class="btn" style="padding:8px 12px;background:#b23a32;font-size:12px">TREAT · FREE</div></div></div></div>
<div style="position:absolute;bottom:12px;left:12px;right:12px"><div class=btn>GIVE THE MEDAL TO REED ▸</div></div>''')
# C: the base as a path you walk
page('C1.html',f'''<div class=bg style="background-image:url({bg2})"></div><div class=tag>C · THE BASE IS THE MENU</div>
<div style="position:absolute;top:0;left:0;right:0;height:300px;background:linear-gradient(#0b1014 35%,#0b101400)"></div><div style="position:absolute;bottom:0;left:0;right:0;height:330px;background:linear-gradient(#0b101400,#0b1014 45%)"></div>
<div style="position:absolute;top:44px;left:14px;right:14px;display:flex;justify-content:space-between;align-items:flex-start"><div><div class=b style="font-size:20px;letter-spacing:.08em">YOUR BASE</div><div class=dim style="font-size:11px">After Chapter 1 · 3 things before you march</div></div><div class="g b" style="font-size:16px">★ 1</div></div>
<svg style="position:absolute;inset:0" width=390 height=760><path d="M300 325 C 230 360,150 300,110 400 S 220 470,290 520" fill=none stroke=#ffd76a stroke-width=3 stroke-dasharray="2 9" stroke-linecap=round /></svg>
'''+''.join(f'''<div style="position:absolute;left:{x}px;top:{y}px;display:flex;align-items:center;gap:8px"><div style="width:40px;height:40px;border-radius:50%;background:{bgc};border:3px solid {bc};display:flex;align-items:center;justify-content:center;font-weight:800;font-size:17px;box-shadow:0 0 0 {gl}px {bc}55">{num}</div><div style="background:#0e151bf2;border-radius:10px;padding:6px 10px;border:1.5px solid {bc}"><div class=b style="font-size:13px;letter-spacing:.06em">{t}</div><div style="font-size:10.5px;color:{sc}">{s}</div></div></div>''' for x,y,num,t,s,bc,bgc,sc,gl in [(214,304,'✓','REPORT','8 men · 5 promoted','#7ed29a','#17402a','#7ed29a',0),(60,380,'1','FIELD HOSPITAL','Rossi is wounded · treat free','#ff6a5e','#5a1f1a','#ff9d93',7),(150,446,'2','BARRACKS','1 perk to choose · 8 recruits','#58c4f6','#143447','#9fd8f5',0),(196,512,'3','BRIEFING TENT','Chapter 2 · Hold the base','#ffd76a','#4a3a10','#ffe08a',0)])+'''
<div style="position:absolute;bottom:12px;left:12px;right:12px"><div class=card style="margin-bottom:8px;display:flex;gap:10px;align-items:center;border-left:3px solid #ff6a5e"><div style="flex:1"><div class=b style="font-size:13px">Next: the field hospital</div><div class=dim style="font-size:11px">Tap the glowing stop, or let me walk you there.</div></div><div class=btn style="padding:9px 14px;background:#b23a32">GO ▸</div></div>
<div style="display:flex;gap:8px"><div class="btn gr" style="flex:1">MENU</div><div class="btn go" style="flex:2;opacity:.55">MARCH OUT · 1 thing left</div></div></div>''')
